export class Vector2 {
    _x;
    _y;
    changed;
    constructor(x = 0, y = 0, onChange) {
        this._x = x;
        this._y = y;
        this.changed = onChange;
    }
    get x() { return this._x; }
    set x(value) { this._x = value; this.changed?.(); }
    get y() { return this._y; }
    set y(value) { this._y = value; this.changed?.(); }
    set(x, y) { this._x = x; this._y = y; this.changed?.(); return this; }
    copy(value) { return this.set(value.x, value.y); }
    clone() { return new Vector2(this._x, this._y); }
    add(value) { return this.set(this._x + value.x, this._y + value.y); }
    sub(value) { return this.set(this._x - value.x, this._y - value.y); }
    multiplyScalar(value) { return this.set(this._x * value, this._y * value); }
    lengthSquared() { return this._x * this._x + this._y * this._y; }
    length() { return Math.sqrt(this.lengthSquared()); }
    normalize() { const length = this.length(); return length > 0 ? this.multiplyScalar(1 / length) : this; }
    dot(value) { return this._x * value.x + this._y * value.y; }
    toArray(target = [], offset = 0) { target[offset] = this._x; target[offset + 1] = this._y; return target; }
}